from common import *
import pickle, collections

def load(job):
    if job=='archived-new':p=ROOT/'backtest/result/horizonp50_20261105_h20_s3000/run_01/artifacts_root/artifacts/trained_model'
    else:p=ROOT/read(BASE/'docs'/f'{PREFIX}-{job}.json')['model']['path']
    with p.open('rb') as f:m=pickle.load(f)
    return m.model.dump_model()['tree_info']

def diff(a,b):
    counts=collections.Counter();first={};max_leaf_delta=0.0
    structure_fields={'split_feature','threshold','decision_type','default_left','missing_type'}
    def visit(x,y,tree,path):
        nonlocal max_leaf_delta
        if not isinstance(x,dict) or not isinstance(y,dict):return
        if ('leaf_value' in x)!=('leaf_value' in y):counts['node_kind']+=1;first.setdefault('node_kind',{'tree':tree,'path':path});return
        for k in sorted(set(x)|set(y)):
            if k in ['left_child','right_child']:
                visit(x.get(k),y.get(k),tree,path+'/'+k);continue
            if x.get(k)!=y.get(k):
                counts[k]+=1;first.setdefault(k,{'tree':tree,'path':path,'a':x.get(k),'b':y.get(k)})
                if k=='leaf_value':max_leaf_delta=max(max_leaf_delta,abs(x[k]-y[k]))
    for i,(x,y) in enumerate(zip(a,b)):visit(x['tree_structure'],y['tree_structure'],i+1,'root')
    sf=[v['tree'] for k,v in first.items() if k in structure_fields or k=='node_kind']
    return {'tree_counts':[len(a),len(b)],'fields_changed':dict(counts),'first_change_by_field':first,'first_structural_difference_tree':min(sf) if sf else None,'max_leaf_difference_at_corresponding_nodes':max_leaf_delta,'note':'Corresponding node fields; default-direction differences are not assumed behaviorally irrelevant. Full valid predictions and selected heads are evaluated separately.'}

if __name__=='__main__':
    register_adapter(__file__)
    a,b=sys.argv[1:3];result={'a':a,'b':b,**diff(load(a),load(b))}
    out=BASE/'docs'/f'{PREFIX}-trees-{a}--{b}.json';write(out,result);print(json.dumps(result,ensure_ascii=False,indent=2))
